"use client";

import React, { useEffect, useState } from "react";

import { AnimatePresence } from "motion/react";

function Page({ children }) {
	const [loader, setLoader] = useState(false);

	useEffect(() => {
		setTimeout(() => {
			setLoader(false);
		}, 2250);
	}, [loader]);

	return (
		<span className="mt-6 block">
			{!loader && (
				<button onClick={() => setLoader(true)}>reset preloader</button>
			)}

			<AnimatePresence mode="wait">{loader && children}</AnimatePresence>

			{!loader && <div>your content goes here</div>}
		</span>
	);
}
export default Page;

"use client";

import { useEffect, useState } from "react";

import { motion } from "motion/react";

import { MouseImageTrail } from "./mouse-image-trail";

// Credit:
// https://www.sparkui.me/components/apple-preloader

const opacity = {
	initial: {
		opacity: 0,
	},
	enter: {
		opacity: 0.75,
		transition: { duration: 1, delay: 0.2 },
	},
};

const slideUp = {
	initial: {
		top: 0,
	},
	exit: {
		top: "-100vh",
		transition: { duration: 0.8, ease: [0.76, 0, 0.24, 1], delay: 0.2 },
	},
};

const words = ["Move", "yo", "mouse", "...", "see", "what", "we", "got"];

export default function Preloader() {
	const [index, setIndex] = useState(0);
	const [dimension, setDimension] = useState({ width: 0, height: 0 });

	useEffect(() => {
		setDimension({ width: window.innerWidth, height: window.innerHeight });
	}, []);

	useEffect(() => {
		if (index === words.length - 1) return;
		setTimeout(
			() => {
				setIndex(index + 1);
			},
			index === 0 ? 1000 : 150
		);
	}, [index]);

	const initialPath = `M0 0 L${dimension.width} 0 L${dimension.width} ${
		dimension.height
	} Q${dimension.width / 2} ${dimension.height + 300} 0 ${
		dimension.height
	}  L0 0`;
	const targetPath = `M0 0 L${dimension.width} 0 L${dimension.width} ${
		dimension.height
	} Q${dimension.width / 2} ${dimension.height} 0 ${dimension.height}  L0 0`;

	const curve = {
		initial: {
			d: initialPath,
			transition: { duration: 0.7, ease: [0.76, 0, 0.24, 1] },
		},
		exit: {
			d: targetPath,
			transition: { duration: 0.7, ease: [0.76, 0, 0.24, 1], delay: 0.3 },
		},
	};

	return (
		<motion.div
			variants={slideUp}
			initial="initial"
			exit="exit"
			className="h-[100vh] w-[100vw] z-[501] fixed top-0 left-0 bg-[#000]"
		>
			<MouseImageTrail
				images={[
					"/itjustworks.jpg",
					"/itjustworks.jpg",
					"/itjustworks.jpg",
					"/itjustworks.jpg",
					"/itjustworks.jpg",
					"/itjustworks.jpg",
					"/itjustworks.jpg",
					"/itjustworks.jpg",
				]}
				renderImageBuffer={150}
				rotationRange={25}
			>
				<div className="h-[100vh] w-[100vw] flex items-center justify-center ">
					{dimension.width > 0 && (
						<>
							<motion.p
								variants={opacity}
								initial="initial"
								animate="enter"
								className="flex bg-clip-text bg-gradient-to-br to-[rgb(255,255,255,0.5)] from-[rgb(255,255,255,0.58)] font-medium text-[42px] items-center absolute z-[1]"
								style={{ color: "transparent" }}
							>
								{words[index]}
							</motion.p>
							<svg className="absolute top-0 w-[100%] h-[calc(100% + 200px)]">
								<motion.path
									variants={curve}
									initial="initial"
									exit="exit"
									fill="#000"
								></motion.path>
							</svg>
						</>
					)}
				</div>
			</MouseImageTrail>
		</motion.div>
	);
}

import React, { MouseEventHandler, ReactNode, useRef } from "react";

import { useAnimate } from "motion/react";

// www.hover.dev/components/other#mouse-image-trail

export const MouseImageTrail = ({
	children,
	// List of image sources
	images,
	// Will render a new image every X pixels between mouse moves
	renderImageBuffer,
	// images will be rotated at a random number between zero and rotationRange,
	// alternating between a positive and negative rotation
	rotationRange,
}: {
	children: ReactNode;
	images: string[];
	renderImageBuffer: number;
	rotationRange: number;
}) => {
	const [scope, animate] = useAnimate();

	const lastRenderPosition = useRef({ x: 0, y: 0 });
	const imageRenderCount = useRef(0);

	const handleMouseMove: MouseEventHandler<HTMLDivElement> = (e) => {
		const { clientX, clientY } = e;

		const distance = calculateDistance(
			clientX,
			clientY,
			lastRenderPosition.current.x,
			lastRenderPosition.current.y
		);

		if (distance >= renderImageBuffer) {
			lastRenderPosition.current.x = clientX;
			lastRenderPosition.current.y = clientY;

			renderNextImage();
		}
	};

	const calculateDistance = (
		x1: number,
		y1: number,
		x2: number,
		y2: number
	) => {
		const deltaX = x2 - x1;
		const deltaY = y2 - y1;

		// Using the Pythagorean theorem to calculate the distance
		const distance = Math.sqrt(deltaX * deltaX + deltaY * deltaY);

		return distance;
	};

	const renderNextImage = () => {
		const imageIndex = imageRenderCount.current % images?.length;
		const selector = `[data-mouse-move-index="${imageIndex}"]`;

		const el = document.querySelector(selector) as HTMLElement;

		el.style.top = `${lastRenderPosition.current.y}px`;
		el.style.left = `${lastRenderPosition.current.x}px`;
		el.style.zIndex = imageRenderCount.current.toString();

		const rotation = Math.random() * rotationRange;

		animate(
			selector,
			{
				opacity: [0, 1],
				transform: [
					`translate(-50%, -25%) scale(0.5) ${
						imageIndex % 2
							? `rotate(${rotation}deg)`
							: `rotate(-${rotation}deg)`
					}`,
					`translate(-50%, -50%) scale(1) ${
						imageIndex % 2
							? `rotate(-${rotation}deg)`
							: `rotate(${rotation}deg)`
					}`,
				],
			},
			{ type: "spring", damping: 15, stiffness: 200 }
		);

		animate(
			selector,
			{
				opacity: [1, 0],
			},
			{ ease: "linear", duration: 0.5, delay: 5 }
		);

		imageRenderCount.current = imageRenderCount.current + 1;
	};

	return (
		<div
			ref={scope}
			className="relative overflow-hidden h-screen z-[502]"
			onMouseMove={handleMouseMove}
		>
			{children}

			{images?.map((img, index) => (
				<img
					className="pointer-events-none absolute left-0 top-0 h-48 w-auto rounded-xl border-2 border-black bg-background object-cover opacity-0"
					src={img}
					alt={`Mouse move image ${index}`}
					key={index + "mouse-image-trail"}
					data-mouse-move-index={index}
				/>
			))}
		</div>
	);
};
